const state={input:structuredClone(DEFAULT_INPUT),route:'home',step:0,tab:'overview',result:null,selected:0,busy:false,inputMode:'kwh',periodMonth:0,monthlyMode:'average',monthlyValue:600,energyCharge:900000,consent:false,dirty:false,errors:[],archive:null,saveEnabled:false,job:0};
state.input.monthlyKwh=Array(12).fill(600);state.input.extrapolated=true;state.input.city='Bandung';state.input.roofArea=40;state.input.maxKwp=8;state.input.horizon=20;
