state.visualRoof={...DEFAULT_ROOF};state.visualSun={...DEFAULT_SUN};state.sunDraft=null;
function getWorker(){if(worker)return worker;worker=new Worker('/src/worker.js',{type:'module'});worker.onmessage=({data})=>{const p=pending.get(data.id);if(!p)return;pending.delete(data.id);data.error?p.reject(data.error):p.resolve(data.result);};worker.onerror=()=>{for(const p of pending.values())p.reject({message:'Mesin kalkulasi tidak dapat dimuat. Muat ulang halaman dan coba lagi.'});pending.clear();worker?.terminate();worker=null;};return worker;}
function runWorker(action,input){return new Promise((resolve,reject)=>{const id=++state.job;pending.set(id,{resolve,reject});getWorker().postMessage({id,action,input});});}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function navigate(route){if(location.hash==='#'+route){state.route=route;render();window.scrollTo(0,0);}else location.hash=route;}
