function house(){return `<svg class="scene" viewBox="0 0 600 580" fill="none" role="img" aria-label="Ilustrasi rumah dengan panel surya, pepohonan dan cahaya matahari"><defs><linearGradient id="land" x1="300" y1="60" x2="300" y2="600"><stop stop-color="#e6ebdd"/><stop offset="1" stop-color="#d5e1bd"/></linearGradient><linearGradient id="wall" x1="200" y1="250" x2="450" y2="450"><stop stop-color="#f8f6e9"/><stop offset="1" stop-color="#d2d8bb"/></linearGradient><linearGradient id="panel" x1="200" y1="210" x2="400" y2="330"><stop stop-color="#335d5b"/><stop offset="1" stop-color="#133c3b"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="15"/></filter><pattern id="grid" width="36" height="36" patternUnits="userSpaceOnUse"><path d="M36 0H0v36" stroke="#b1c2a3" stroke-width=".6" opacity=".55"/></pattern></defs><rect width="600" height="580" fill="url(#land)"/><rect width="600" height="580" fill="url(#grid)" opacity=".5"/><circle cx="466" cy="113" r="43" fill="#e9bd63"/><circle cx="466" cy="113" r="68" stroke="#c9d2b7" stroke-dasharray="3 8"/><circle cx="466" cy="113" r="100" stroke="#c9d2b7" opacity=".6"/><path d="M-30 420q210-100 450 50t220-20M-30 440q210-100 450 50t220-20M-30 460q210-100 450 50t220-20" stroke="#a9bf90" opacity=".5"/><ellipse cx="315" cy="419" rx="180" ry="39" fill="#6d8754" opacity=".22" filter="url(#shadow)"/><path d="m100 362 222-118 205 111-222 119-205-112Z" fill="#d1deb4"/><path d="m100 362 205 112v12L100 374v-12Z" fill="#bbcea0"/><path d="m305 474 222-119v12L305 486v-12Z" fill="#a5be8b"/><path d="m192 272 139-76 140 76v127l-137 74-142-77V272Z" fill="url(#wall)"/><path d="m334 350 137-78v127l-137 74V350Z" fill="#d8dbc0"/><path d="m171 276 145-138 166 88-143 145-168-95Z" fill="#a7b695"/><path d="m171 276 168 95v9l-168-95v-9Z" fill="#7b9677"/><path d="m339 371 143-145v10L339 380v-9Z" fill="#657e64"/><path d="m187 265 132-111 145 77-129 120-148-86Z" fill="#e6e8d5"/><g stroke="#87aaa3" stroke-width="1.5"><path d="m215 258 45-38 49 27-43 39-51-28Z" fill="url(#panel)"/><path d="m265 215 45-38 49 27-43 39-51-28Z" fill="url(#panel)"/><path d="m269 289 44-39 50 27-44 40-50-28Z" fill="url(#panel)"/><path d="m319 245 43-38 50 26-43 40-50-28Z" fill="url(#panel)"/><path d="m239 237 50 28m-50 6 45-38m4-37 50 28m-51 6 45-38m-38 62 49 27m-50 6 44-39m29-18 50 28m-50 6 44-39" opacity=".7"/></g><path d="m218 325 37 20v54l-37-20v-54Z" fill="#617d6b"/><path d="m222 331 29 16v38l-29-16v-38Z" fill="#9eb3a1"/><path d="m274 355 37 20v85l-37-20v-85Z" fill="#879777"/><path d="m369 349 65-36v50l-65 36v-50Z" fill="#6e8976"/><path d="M400 332v49m-31-7 65-36" stroke="#e9eddb" stroke-width="3"/><path d="m278 436 29 16v8l-29-16v-8Z" fill="#657d62"/><circle cx="300" cy="416" r="2" fill="#dae5be"/><path d="M144 327v75m-17-47 17 19 17-24" stroke="#71835b" stroke-width="6"/><ellipse cx="144" cy="318" rx="33" ry="51" fill="#8eaa69"/><ellipse cx="134" cy="312" rx="23" ry="39" fill="#a4bc7e"/><path d="M487 308v73" stroke="#71835b" stroke-width="6"/><ellipse cx="487" cy="300" rx="32" ry="48" fill="#7b985e"/><ellipse cx="478" cy="292" rx="21" ry="35" fill="#94ad71"/><path d="m406 409 22-12m-12 18 22-12m-12 18 22-12" stroke="#f7f8e8" stroke-width="8"/><path d="m443 433 36-18" stroke="#92ad73" stroke-width="10"/><path d="m109 398 28 15" stroke="#b3c990" stroke-width="9"/></svg>`;}
function home(){return `<main id="main" class="wrap" tabindex="-1"><section class="hero"><div class="hero-copy"><div class="eyebrow">Langkah kecil untuk energi yang lebih baik</div><h1>Atapmu punya<br>potensi.<br><em>Hitung dengan jelas.</em></h1><p>Sebelum beralih ke panel surya, pahami berapa energinya, berapa biayanya, dan apa yang masuk akal untukmu.</p><div class="hero-actions"><a class="btn primary" href="#simulator">Hitung potensi atapmu ${icon('arrow')}</a><button class="btn" data-action="demo">Lihat contoh ${icon('chart')}</button></div><div class="hero-proof"><span>${icon('check')} Tanpa akun</span><span>${icon('check')} Asumsi terbuka</span><span>${icon('check')} Tidak jual data</span></div></div><div class="hero-art">${house()}<div class="art-top"><span></span> ENERGI BAIK DIMULAI DARI RUMAH</div><div class="solar-label">Bukan sekadar pasang panel.<strong>Kenali potensinya.</strong><span class="muted">Ilustrasi sistem PLTS atap</span></div><div class="art-stat"><div><span class="small">Dirancang untuk</span><strong>Rumah, sekolah & UMKM</strong><p>Satu lokasi. Banyak kemungkinan.</p></div><div><span class="small">Prinsip kami</span><strong>Semua angka punya cerita</strong><p>Sumber dan asumsi selalu terlihat.</p></div></div></div></section><div class="intro-row"><div class="mini-feature">${icon('sun')}<div><strong>Energi yang benar-benar terpakai</strong><p>Hitung pemakaian sendiri, bukan sekadar produksi.</p></div></div><div class="mini-feature">${icon('layers')}<div><strong>Bandingkan, jangan menebak</strong><p>Lihat opsi kapasitas bersama baseline tanpa PLTS.</p></div></div><div class="mini-feature">${icon('shield')}<div><strong>Transparan sejak awal</strong><p>Estimasi, asumsi, dan keterbatasan tidak disembunyikan.</p></div></div></div><section class="section"><div class="section-heading"><div><div class="eyebrow">Dari penasaran menjadi paham</div><h2>Keputusan besar.<br>Tiga langkah sederhana.</h2></div><p>Tak perlu jadi ahli kelistrikan untuk memulai. Kami bantu membaca angkanya.</p></div><div class="steps-grid">${[['01','home','Ceritakan kebutuhanmu','Masukkan pemakaian listrik, kondisi atap, dan kebiasaan aktivitas.'],['02','chart','Jelajahi kemungkinan','Bandingkan kapasitas, aliran energi, biaya, dan arus kas secara berdampingan.'],['03','file','Bawa hasilnya berdiskusi','Simpan hasil beserta asumsi untuk dibahas dengan penyedia dan tenaga ahli.']].map(([n,i,h,p])=>`<article class="step-card"><div class="num">${n} ${icon(i)}</div><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section><section class="statement"><h2>Lebih baik tahu batasnya,<br><span>daripada percaya janji.</span></h2><div><p>Panelin adalah alat eksplorasi awal, bukan penawaran harga atau jaminan penghematan. Versi ini memakai contoh sintetis atau data yang kamu isi sendiri, dengan seluruh asumsi dapat diperiksa.</p><a class="btn lime compact" href="#metodologi">Kenali cara kami menghitung ${icon('arrow')}</a></div></section><div style="height:65px"></div></main>`;}
function field(key,label,unit='',opts={}){const value=state.input[key];return `<div class="field ${opts.wide?'wide':''}"><label for="${key}">${label}${opts.optional?'<small>Opsional</small>':''}</label><div class="${unit?'suffix-input':''}"><input id="${key}" name="${key}" ${opts.type==='text'?'type="text"':'type="number" inputmode="decimal"'} value="${esc(value??'')}" ${opts.step?`step="${opts.step}"`:'step="any"'} ${opts.min!=null?`min="${opts.min}"`:''} ${opts.max!=null?`max="${opts.max}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}>${unit?`<span>${unit}</span>`:''}</div>${opts.hint?`<span class="hint">${opts.hint}</span>`:''}</div>`;}
function select(key,label,options,hint=''){return `<div class="field"><label for="${key}">${label}</label><select id="${key}" name="${key}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(state.input[key])===String(v)?'selected':''}>${t}</option>`).join('')}</select>${hint?`<span class="hint">${hint}</span>`:''}</div>`;}
function notice(text,type=''){return `<div class="notice ${type}">${icon('info')}<p>${text}</p></div>`;}
function inputStep(){return `<h2>Mulai dari listrik yang kamu pakai.</h2><p>Jenis bangunan membantu menyusun profil aktivitas. Tarif tetap kamu tentukan sendiri.</p><div class="segment-options">${[['household','home','Rumah tangga'],['school','school','Sekolah'],['business','shop','UMKM']].map(([v,i,l])=>`<button type="button" data-action="segment" data-value="${v}" class="segment-card ${state.input.segment===v?'selected':''}" aria-pressed="${state.input.segment===v}">${icon(i)}${l}</button>`).join('')}</div><div class="mode-picker" aria-label="Metode input konsumsi"><button type="button" data-action="input-mode" data-value="kwh" class="${state.inputMode==='kwh'?'selected':''}">Punya angka kWh</button><button type="button" data-action="input-mode" data-value="charge" class="${state.inputMode==='charge'?'selected':''}">Dari biaya energi</button></div><div class="fields">${field('year','Tahun model','',{min:2000,max:2100,step:1})}<div class="field"><label for="periodMonth">Bulan pemakaian</label><select name="periodMonth" id="periodMonth">${fullMonths.map((m,i)=>`<option value="${i}" ${state.periodMonth===i?'selected':''}>${m}</option>`).join('')}</select></div>${state.inputMode==='kwh'?`<div class="field wide"><label for="monthlyValue">Konsumsi listrik bulan tersebut</label><div class="suffix-input"><input id="monthlyValue" name="monthlyValue" type="number" inputmode="decimal" min="0" step="any" value="${esc(state.monthlyValue)}"><span>kWh</span></div><span class="hint">Cek kWh pemakaian pada rekening atau aplikasi PLN. Angka nol berbeda dari data kosong.</span></div>`:`<div class="field wide"><label for="energyCharge">Biaya komponen energi saja</label><div class="suffix-input"><input id="energyCharge" name="energyCharge" type="number" min="0" step="any" value="${esc(state.energyCharge)}"><span>Rp</span></div><span class="hint">Tidak termasuk pajak, administrasi, biaya tetap, atau nominal pembelian token.</span></div>`}${field('tariff','Tarif energi','Rp/kWh',{min:0,hint:'Angka awal Rp1.500 adalah contoh, bukan tarif resmi. Cocokkan rekening dengan <a href="https://www.pln.co.id/penyesuaian-tarif-id" target="_blank" rel="noopener noreferrer">informasi tarif PLN</a>.'})}${field('tariffGroup','Golongan / catatan tarif','',{type:'text',hint:'Isi sesuai rekening atau sumber yang kamu gunakan.'})}${field('tariffPeriod','Periode berlaku tarif','',{type:'text',wide:true})}</div>${state.inputMode==='charge'?notice('Konversi hanya berlaku untuk biaya energi terpisah dengan tarif flat positif. Nominal total tagihan atau token tanpa periode tidak boleh dipakai.','amber'):''}<h3 class="subheading">Cakupan data konsumsi</h3><div class="mode-picker"><button type="button" data-action="monthly-mode" data-value="average" class="${state.monthlyMode==='average'?'selected':''}">Satu bulan sebagai perkiraan</button><button type="button" data-action="monthly-mode" data-value="full" class="${state.monthlyMode==='full'?'selected':''}">Isi 12 bulan</button></div>${state.monthlyMode==='average'?`<label class="checkbox-row"><input type="checkbox" name="consent" ${state.consent?'checked':''}><span>Saya memilih mengasumsikan nilai bulan ini sama untuk 12 bulan. Sebelas bulan lainnya akan ditandai <strong>perkiraan</strong>, bukan data terukur.</span></label>`:`<div class="months">${months.map((m,i)=>`<div class="field"><label for="month-${i}">${m} (kWh)</label><input type="number" min="0" step="any" name="month-${i}" id="month-${i}" value="${esc(state.input.monthlyKwh[i]??'')}" ${state.input.hourlyData?.loadKwh?'readonly aria-readonly="true"':''}></div>`).join('')}</div>`}`;}
function geographicDraftErrors(){
 if(!state.input.geo)return [];
 const labels={latitude:'lintang',longitude:'bujur',timezone:'zona waktu',heading:'arah depan bangunan'};
 const fields=(state.sunDraft?.invalidFields||[]).filter(key=>Object.hasOwn(labels,key));
 return fields.length?[{message:'Perbaiki '+fields.map(key=>labels[key]).join(', ')+' pada Lokasi & atap sebelum melanjutkan. Nilai terakhir yang valid tidak akan dipakai untuk melewati isian yang salah.'}]:[];
}
function acceptSunDraft(draft){state.sunDraft=draft;if(geographicDraftErrors().length){state.dirty=true;const stale=$('[data-stale-result]');if(stale)stale.hidden=false;}}
function syncGeographicInput(){
 if(!state.input.geo)return;
 const {type,width,length,pitch,orientation,surface}=state.visualRoof;
 const geo={...state.input.geo,latitude:state.visualSun.latitude,longitude:state.visualSun.longitude,heading:state.visualSun.heading,roof:{type,width,length,pitch,orientation,surface}};
 if(JSON.stringify(geo)!==JSON.stringify(state.input.geo)||state.input.timezone!==state.visualSun.timezone){state.input.geo=geo;state.input.timezone=state.visualSun.timezone;state.dirty=true;}
 const zone=$('#timezone');if(zone)zone.value=state.input.timezone;
 const status=$('[data-geo-status]');if(status)status.textContent=state.input.geo?`Aktif: ${num(geo.latitude,4)}, ${num(geo.longitude,4)} · arah depan ${num(geo.heading)}° · ${geo.roof.type}, kemiringan ${num(['flat','l'].includes(geo.roof.type)?0:geo.roof.pitch)}°. Hitung ulang setelah perubahan.`:'';
 const stale=$('[data-stale-result]');if(stale&&state.dirty)stale.hidden=false;
}
function geographicControls(){const g=state.input.geo;return `<section class="panel" style="margin-top:22px"><h3>Hubungkan posisi & bentuk atap ke estimasi <small>Opsional</small></h3><p>Tidak tahu koordinat atau arah rumah? Lewati bagian ini. Simulasi sederhana tetap bisa dipakai dengan batasannya.</p><label class="checkbox-row"><input type="checkbox" id="geo-enabled" ${g?'checked':''} ${state.input.hourlyData?.productionKwhPerKwp?'disabled':''}><span><strong>Gunakan data geografis dan atap 3D.</strong> Saya sudah menyesuaikan lokasi, zona waktu, arah depan bangunan, kemiringan, dan bidang atap di atas. Angka awal Bandung hanyalah contoh.</span></label>${g?`<p class="hint" data-geo-status>Data 3D terhubung. Perubahan posisi, arah, bentuk, dan bidang atap memengaruhi estimasi setelah dihitung ulang.</p>${notice('Yield bulanan di bawah sekarang berarti referensi AC bidang horizontal di lokasi ini. Jangan gunakan yield yang sudah dikoreksi untuk kemiringan/arah atap, agar tidak dikoreksi dua kali. Koordinat saja tidak menyediakan data cuaca.','amber')}<details class="details"><summary>Asumsi cahaya & rugi tambahan</summary><div class="fields">${[['diffuseFraction','Fraksi cahaya difus',0,1,'Awal 0,5 adalah asumsi skenario, bukan cuaca lokasi.'],['albedo','Pantulan tanah (albedo)',0,1,'Awal 0,2 adalah asumsi skenario.'],['additionalLoss','Rugi tambahan yang belum masuk yield',0,1,'Awal 0. Jangan masukkan bayangan/losses yang sudah masuk sumber.']].map(([key,label,min,max,hint])=>`<div class="field"><label for="geo-${key}">${label}</label><input id="geo-${key}" name="geo-${key}" type="number" min="${min}" max="${max}" step="0.01" value="${g[key]}"><span class="hint">${hint}</span></div>`).join('')}</div></details>`:notice('Tanpa hubungan ini, atap 3D hanya ilustrasi. Profil produksi bulanan memakai perkiraan pukul 06–18, bukan posisi rumah.')}<p class="small muted">Perhitungan menelusuri matahari sepanjang tahun model, bukan hanya tanggal/jam yang sedang ditampilkan. Bayangan pohon, gedung sekitar, suhu panel, cuaca harian, dan struktur belum dihitung.</p></section>`;}
function hourlyImportControls(){const d=state.input.hourlyData;return `<details class="details"><summary>Punya data per jam? Impor CSV (opsional)</summary><p>Gunakan ekspor yang disiapkan penyedia/model surya atau meter. Format harus energi AC per jam, bukan daya sesaat. Untuk mayoritas pengguna, data bulanan di atas sudah cukup untuk eksplorasi awal.</p>${notice('Impor tidak membuktikan data benar. Produksi harus kWh AC per kWp DC; beban harus konsumsi total gedung, bukan impor/neto PLN. Seri produksi sudah memuat orientasi/losses, jadi hubungan geografis harus dimatikan.')}<p class="small">Isi sumber manual dan periode terlebih dahulu. CSV: timestamp,production_kwh_per_kwp,load_kwh. Salah satu kolom energi boleh dihapus seluruhnya. Timestamp adalah awal jam ISO dengan Z atau offset. Perlu setahun lokal lengkap; sel kosong, duplikat, dan jam hilang ditolak. Desimal memakai titik.</p><div class="storage-actions"><button type="button" class="btn compact" data-action="hourly-template">Unduh template kosong</button><label class="btn compact" for="hourly-file">Pilih CSV</label><input id="hourly-file" type="file" accept="text/csv,.csv" style="max-width:100%"></div>${d?`<p class="hint">Aktif: ${esc(d.sourceName)} · ${d.year} · ${esc(d.timezone)} · ${d.productionKwhPerKwp?'produksi AC':''}${d.productionKwhPerKwp&&d.loadKwh?' + ':''}${d.loadKwh?'beban gedung':''}. Total bulanan mengikuti seri. Data tidak dikirim ke server.</p><button type="button" class="btn compact" data-action="remove-hourly">Lepas data per jam</button>`:''}</details>`;}
async function importHourlyFile(file){if(!file)return;if(file.size>4*1024*1024){notify('CSV melebihi 4 MiB.');return;}collect();if(state.input.mode!=='manual'){notify('Pilih data manual dan isi nama sumber/periode sebelum impor.');return;}try{const parsed=parseHourlyCSV(await file.text(),{year:state.input.year,timezone:state.input.timezone,sourceName:state.input.sourceName,sourcePeriod:state.input.sourcePeriod});if(parsed.data.productionKwhPerKwp&&state.input.geo)throw new Error('Matikan hubungan geografis sebelum mengimpor produksi AC yang sudah memuat orientasi.');const next={...state.input,hourlyData:parsed.data};if(parsed.monthlyYield)next.monthlyYield=parsed.monthlyYield;if(parsed.monthlyKwh){next.monthlyKwh=parsed.monthlyKwh;next.extrapolated=false;}const check=validateInput(next);if(!check.valid)throw new Error(check.errors.join(' '));state.input=next;if(parsed.monthlyKwh){state.monthlyMode='full';state.monthlyValue=next.monthlyKwh[0];}state.result=null;state.dirty=true;state.errors=[];render();notify('Data per jam dimuat. Total bulanan mengikuti file; sumber tetap perlu kamu verifikasi.');}catch(e){notify('Impor ditolak: '+e.message);}}
function downloadHourlyTemplate(){const blob=new Blob([hourlyCSVTemplate(state.input.year,state.input.timezone)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Panelin-template-${state.input.year}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Template kosong disiapkan. Isi data nyata sebelum mengimpor; kosong tidak berarti nol.');}
function roof3d(){return roofViewHTML(state.visualRoof,{sun:state.visualSun,energyLinked:!!state.input.geo,panelCount:selected()?.panelCount??0});}
function roofStep(){return `<h2>Setiap atap punya ceritanya.</h2><p>Jelajahi bentuk atapmu di bawah. Data atap untuk kalkulasi tetap diisi terpisah; boleh kosong jika belum diketahui.</p>${roofViewHTML(state.visualRoof,{compact:true,sun:state.visualSun,energyLinked:!!state.input.geo})}${geographicControls()}<h3 class="subheading">Data lokasi & batas kalkulasi</h3><div class="fields">${field('city','Kota / kabupaten','',{type:'text'})}${select('timezone','Zona waktu',[['Asia/Jakarta','WIB · Asia/Jakarta'],['Asia/Makassar','WITA · Asia/Makassar'],['Asia/Jayapura','WIT · Asia/Jayapura']])}${field('roofArea','Luas efektif atap','m²',{min:0,optional:true,placeholder:'Belum diketahui',hint:'Area yang benar-benar tersedia, setelah jarak aman dan hambatan.'})}${field('budget','Batas anggaran','Rp',{min:0,optional:true,placeholder:'Tidak dibatasi'})}${field('roofTilt','Catatan kemiringan survei','derajat',{min:0,max:90,optional:true,placeholder:'Belum diketahui'})}${field('roofAzimuth','Catatan azimut survei','derajat',{min:0,max:359.999,optional:true,placeholder:'Belum diketahui',hint:'0° utara, 90° timur, 180° selatan, 270° barat.'})}${select('shading','Catatan bayangan (belum dimodelkan)',[['','Belum diketahui'],['0','Minim bayangan'],['0.2','Sebagian terhalang'],['0.5','Banyak terhalang']])}${field('maxKwp','Kapasitas maksimum eksplorasi','kWp DC',{min:.5,max:30,hint:'Jika luas atap kosong, ukuran ini hanya eksplorasi manual.'})}</div>${notice('Luas hanya menjadi batas area sederhana. Arah dan kemiringan dari 3D hanya dipakai bila hubungan geografis aktif. Isian kemiringan/azimut/bayangan di bawah adalah catatan survei, bukan koreksi tambahan. Aktifkan hubungan geografis di atas untuk memakai posisi dan bidang 3D dalam estimasi. Geometri bukan bukti kelayakan pemasangan.')}<h3 class="subheading">Sumber produksi surya</h3><div class="mode-picker"><button type="button" data-action="data-mode" data-value="demo" class="${state.input.mode==='demo'?'selected':''}">Contoh sintetis</button><button type="button" data-action="data-mode" data-value="manual" class="${state.input.mode==='manual'?'selected':''}">Data yield manual</button></div>${state.input.mode==='demo'?notice('ASUMSI AWAL · Data surya ini sintetis, bukan data radiasi kota yang kamu pilih. Hasil tidak diberi peringkat rekomendasi personal.','amber'):`<div class="fields">${field('sourceName','Nama / referensi sumber yield','',{type:'text',wide:true,hint:'Wajib: sumber yang kamu gunakan. Tidak diperiksa otomatis oleh aplikasi.'})}${field('sourcePeriod','Periode dataset surya','',{type:'text',wide:true})}</div>${notice(state.input.hourlyData?.productionKwhPerKwp?'Produksi memakai seri AC per jam dari file. Total bulanan ditampilkan untuk audit.':state.input.geo?'Yield adalah referensi AC horizontal. Posisi dan bidang 3D mengubah estimasi dengan asumsi transposisi sederhana.':'Yield AC bulanan dibagi ke profil jam sintetis. Data manual belum diverifikasi. Jangan kurangi losses yang sama dua kali.','amber')}`}<details class="details" ${state.input.mode==='manual'?'open':''}><summary>Periksa yield bulanan (kWh/kWp per bulan)</summary><div class="months">${months.map((m,i)=>`<div class="field"><label for="yield-${i}">${m}</label><input type="number" min="0" step="any" id="yield-${i}" name="yield-${i}" value="${esc(state.input.monthlyYield[i])}" ${state.input.hourlyData?.productionKwhPerKwp?'readonly aria-readonly="true"':''}></div>`).join('')}</div></details>${hourlyImportControls()}`;}
function profileChart(){const i=state.input;const values=Array.from({length:24},(_,h)=>(h>=i.startHour&&h<i.endHour?1:i.baseLoad));return barChart(values,values.map((_,h)=>h%4===0?String(h).padStart(2,'0')+'.00':''),'#3c6650','Bobot relatif pemakaian per jam');}
function scheduleStep(){return `<h2>Kapan listrikmu paling dibutuhkan?</h2><p>Panel surya paling berguna saat produksinya bertepatan dengan pemakaian. Jadwal ini adalah perkiraan, bukan pembacaan meter.</p><div class="fields"><div class="field wide"><span class="label">Hari aktivitas utama</span><div class="day-picks">${days.map((d,i)=>`<label><input type="checkbox" name="day-${i}" ${state.input.activeDays.includes(i)?'checked':''}><span>${d}</span></label>`).join('')}</div></div>${field('startHour','Aktivitas mulai','jam',{min:0,max:23,step:1})}${field('endHour','Aktivitas selesai','jam',{min:1,max:24,step:1})}${field('baseLoad','Bobot beban dasar','',{min:0,max:1,step:.05,hint:'Bobot yang tetap aktif di luar jam utama, misalnya kulkas dan perangkat siaga.'})}<div class="field"><label for="holidays">Tanggal tutup / libur <small>Opsional</small></label><input name="holidays" id="holidays" type="text" value="${esc(state.input.holidays.join(', '))}" placeholder="2025-01-01, 2025-12-25"><span class="hint">Pisahkan dengan koma. Tahun harus sesuai tahun model.</span></div></div><div class="panel" style="margin-top:25px;background:#f7f9f2"><div class="chart-head"><h3>Ritme pemakaian harian</h3><span class="pill">Profil perkiraan</span></div>${profileChart()}<p class="chart-note">Grafik bobot hari aktif. Total kWh setiap bulan dinormalisasi ke input konsumsi, termasuk hari tutup dan libur.</p><details class="details"><summary>Lihat tabel bobot 24 jam</summary><div class="table-wrap" role="region" aria-label="Tabel profil per jam" tabindex="0"><table><thead><tr><th>Jam</th><th>Bobot hari aktif</th><th>Bobot hari tutup</th></tr></thead><tbody>${Array.from({length:24},(_,h)=>`<tr><td>${String(h).padStart(2,'0')}.00</td><td>${num((h>=state.input.startHour&&h<state.input.endHour?1:state.input.baseLoad),2)}</td><td>${num(state.input.baseLoad,2)}</td></tr>`).join('')}</tbody></table></div></details></div>${state.input.hourlyData?.loadKwh?notice('Seri beban per jam impor sedang aktif. Jadwal di halaman ini tidak mengubah beban sampai seri dilepas di langkah Lokasi & atap.','amber'):''}${notice('Mengubah jadwal dapat mengubah penghematan meskipun total kWh tetap sama. Surplus siang tidak menghapus impor dari jaringan pada malam hari.')}`;}
function financeStep(){return `<h2>Angka yang masuk akal dimulai dari asumsi.</h2><p>Angka awal adalah contoh biaya, bukan penawaran vendor. Ubah sesuai penawaran atau asumsi risetmu.</p><div class="fields">${field('capexPerKwp','Paket sistem per kWp','Rp/kWp',{min:0,hint:'Termasuk panel, inverter, struktur, dan pemasangan. Jangan dihitung ulang sebagai komponen tambahan.'})}${field('fixedCapex','Biaya tetap di luar paket','Rp',{min:0,hint:'Hanya biaya yang belum masuk paket di samping.'})}${field('annualOpex','Pemeliharaan tahunan','Rp/tahun',{min:0})}${field('horizon','Horizon simulasi','tahun',{min:1,max:30,step:1})}${field('replacementYear','Tahun penggantian inverter','tahun',{min:1,max:30,step:1})}${field('replacementCost','Biaya penggantian inverter','Rp',{min:0})}</div><details class="details"><summary>Parameter teknis dan finansial lanjutan</summary><div class="fields">${field('panelWp','Daya satu modul','Wp',{min:100,max:1000})}${field('panelArea','Luas satu modul','m²',{min:.1})}${field('installationFactor','Faktor ruang pemasangan','×',{min:1})}${field('inverterKw','Rating inverter terpisah','kW AC',{min:.1,hint:'Membatasi rata-rata keluaran AC per jam. Bukan model efisiensi atau clipping subjam.'})}${field('degradation','Degradasi tahunan','fraksi',{min:0,max:.2,hint:'0,005 berarti 0,5% per tahun.'})}${field('discountRate','Tingkat diskonto','fraksi',{min:0,max:.5,hint:'0,06 berarti 6%. Basis nominal konsisten.'})}${field('tariffEscalation','Kenaikan tarif tahunan','fraksi',{min:-.1,max:.2,hint:'Default 0. Bukan prediksi tarif PLN.'})}${field('opexEscalation','Kenaikan OPEX tahunan','fraksi',{min:-.1,max:.2})}</div></details>${notice('Model on-grid tanpa baterai. Kredit finansial surplus Rp0. Penghematan hanya komponen energi, bukan kepastian total tagihan. Pajak, rekening minimum, persetujuan PLN, dan kelayakan instalasi belum dimodelkan.','amber')}<div class="panel" style="background:#f3f6ed"><h3>Siap untuk melihat kemungkinannya?</h3><p>Tidak ada data yang dikirim ke vendor. Kalkulasi berlangsung di browser, tanpa membuat akun.</p><label class="checkbox-row"><input type="checkbox" name="saveEnabled" ${state.saveEnabled?'checked':''}><span>Simpan input di browser ini setelah hasil berhasil dihitung. Opsional dan dapat dihapus kapan saja.</span></label></div>`;}
function wizard(){const steps=['Pemakaian','Lokasi & atap','Aktivitas','Biaya'];return `<main id="main" class="wrap" tabindex="-1"><div class="page-top"><div class="page-meta"><a class="back" href="#home">${icon('back')} Kembali ke beranda</a><span class="pill ${state.input.mode==='demo'?'amber':''}">${state.input.mode==='demo'?'Estimasi · asumsi awal':'Estimasi · data manual'}</span></div><h1>Kenali potensi atapmu.</h1><p>Empat langkah singkat untuk menjelajahi pilihan PLTS. Angka yang belum kamu tahu boleh tetap belum diketahui.</p></div><div class="sim-layout"><section class="wizard" aria-label="Formulir simulasi"><nav class="progress" aria-label="Langkah simulasi">${steps.map((s,i)=>`<button type="button" data-action="step" data-value="${i}" class="${i===state.step?'active':i<state.step?'done':''}" ${i===state.step?'aria-current="step"':''}><span>${i<state.step?'✓':i+1}</span>${s}</button>`).join('')}</nav><form id="simulation-form" novalidate><div class="form-body">${state.errors.length?`<div class="notice error" role="alert"><p><strong>Periksa kembali inputmu.</strong><br>${state.errors.map(e=>esc(e.message||e)).join('<br>')}</p></div>`:''}${[inputStep,roofStep,scheduleStep,financeStep][state.step]()}</div><div class="form-footer">${state.step?`<button type="button" class="btn ghost" data-action="prev">${icon('back')} Sebelumnya</button>`:'<span class="small">Langkah 1 dari 4</span>'}<button type="submit" class="btn primary">${state.step===3?'Hitung simulasiku':'Lanjutkan'} ${icon('arrow')}</button></div></form></section><aside class="sim-aside"><div class="aside-card dark"><span class="pill dark">Rencana energimu</span><h3>Sedikit data,<br>lebih banyak kejelasan.</h3><div class="aside-stat"><span>Kebutuhan</span><strong>${{household:'Rumah tangga',school:'Sekolah',business:'UMKM'}[state.input.segment]}</strong></div><div class="aside-stat"><span>Konsumsi / tahun</span><strong>${num(state.input.monthlyKwh.reduce((a,b)=>a+(Number(b)||0),0))} kWh</strong></div><div class="aside-stat"><span>Lokasi</span><strong>${esc(state.input.city||'Belum diisi')}</strong></div><div class="aside-stat"><span>Batas atap</span><strong>${state.input.roofArea==null?'Belum diketahui':num(state.input.roofArea)+' m²'}</strong></div><div class="aside-separator"></div><p>Kapasitas lebih besar belum tentu lebih tepat. Waktu pemakaian sama pentingnya dengan luas atap.</p></div><div class="aside-card">${icon('shield')}<h3>Kamu yang pegang datanya.</h3><p>Input tetap di browser. Tidak ada nomor pelanggan, alamat lengkap, atau kontak yang kami minta.</p></div><div class="aside-note">${icon('info')}Hasil adalah eksplorasi awal, bukan jaminan penghematan, desain teknis, atau persetujuan pemasangan.</div></aside></div></main>`;}
function barChart(values,labels,color='#365a45',label='Grafik energi'){const w=600,h=185,max=Math.max(...values,1),gap=5,bw=(w-42)/values.length;return `<svg class="chart-box" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}" preserveAspectRatio="none"><line x1="25" y1="150" x2="590" y2="150" stroke="#dde4d9"/><line x1="25" y1="80" x2="590" y2="80" stroke="#e7ece1" stroke-dasharray="3 5"/>${values.map((v,i)=>`<rect x="${25+i*bw}" y="${150-v/max*125}" width="${Math.max(2,bw-gap)}" height="${v/max*125}" rx="3" fill="${color}"/><text x="${25+i*bw+(bw-gap)/2}" y="174" text-anchor="middle" font-size="10" fill="#687a6b">${esc(labels[i]||'')}</text>`).join('')}</svg>`;}
function lineChart(values,label){const w=600,h=190,lo=Math.min(0,...values),hi=Math.max(1,...values),y=v=>150-(v-lo)/(hi-lo)*125,pts=values.map((v,i)=>`${25+i/(Math.max(1,values.length-1))*555},${y(v)}`).join(' ');return `<svg class="chart-box" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}" preserveAspectRatio="none"><line x1="25" x2="580" y1="${y(0)}" y2="${y(0)}" stroke="#a4b69d" stroke-dasharray="4 4"/><polyline points="${pts}" fill="none" stroke="#41664b" stroke-width="3" stroke-linejoin="round"/><circle cx="580" cy="${y(values.at(-1))}" r="4" fill="#41664b"/><text x="25" y="180" font-size="10" fill="#60756b">Tahun 0</text><text x="550" y="180" font-size="10" fill="#60756b">${values.length-1}</text><text x="25" y="16" font-size="10" fill="#60756b">${esc(moneyShort(hi))}</text><text x="25" y="165" font-size="10" fill="#60756b">${esc(moneyShort(lo))}</text></svg>`;}
function selected(){return state.result?.choices?.[state.selected]||state.result?.baseline;}
function metrics(c){return `<div class="metrics">${[['Estimasi produksi / tahun',num(c.annualGeneration),'kWh',state.result.input.hourlyData?.productionKwhPerKwp?'Produksi AC dari seri impor pengguna.':state.result.input.geo?'Estimasi geografis, bukan pengukuran cuaca.':'Profil AC bulanan sintetis, bukan pengukuran.'],['Energi yang dipakai sendiri',num(c.annualSelfConsumption),'kWh / tahun',`${pct(c.selfConsumptionRatio)} dari produksi surya.`],['Penghematan energi / tahun',moneyShort(c.annualSavings),'','Tahun pertama. Bukan total tagihan.'],['Balik modal dalam model',c.payback==null?'Belum tercapai':num(c.payback,1),c.payback==null?'':'tahun',`Horizon ${state.result.input.horizon} tahun · tak terdiskonto.`]].map(([l,v,u,n])=>`<div class="metric"><div class="label">${l}</div><div class="value">${v} <span class="unit">${u}</span></div><div class="note">${n}</div></div>`).join('')}</div>`;}
function candidateCards(){const r=state.result;return `<div class="comparison"><article class="option baseline"><div class="label">Pembanding awal</div><div class="kwp">0 <small>kWp DC</small></div><div class="panels">Tanpa PLTS · seluruh beban dari jaringan</div><div class="cost"><small>Investasi awal</small>Rp0</div><p class="small muted" style="margin:14px 0 0">Impor ${num(r.baseline.annualImport)} kWh/tahun<br>Manfaat PLTS Rp0</p></article>${r.choices.map((c,i)=>`<article class="option ${state.selected===i?'selected':''}"><div class="label">${r.input.mode==='demo'?'Eksplorasi '+String(i+1).padStart(2,'0'):esc(c.label)}</div><div class="kwp">${num(c.kwp,2)} <small>kWp DC</small></div><div class="panels">${c.panelCount} panel · ${num(c.area,1)} m²<br>Inverter ${num(c.inverterKw,1)} kW AC</div><div class="cost"><small>Estimasi investasi awal</small>${moneyShort(c.capex)}</div><button class="btn full ${state.selected===i?'primary':''}" data-action="candidate" data-value="${i}" aria-pressed="${state.selected===i}">${state.selected===i?'Sedang dilihat':'Lihat rincian'} ${icon(state.selected===i?'check':'arrow')}</button></article>`).join('')}</div>`;}
function energyTable(c){return `<div class="table-wrap" role="region" tabindex="0" aria-label="Rincian aliran energi bulanan"><table><thead><tr><th>Bulan</th><th>Beban (kWh)</th><th>Produksi (kWh)</th><th>Dipakai sendiri</th><th>Impor jaringan</th><th>Surplus</th></tr></thead><tbody>${(c.monthly||[]).map((m,i)=>`<tr><td>${months[i]}</td><td>${num(m.load??m.consumption??state.result.input.monthlyKwh[i],1)}</td><td>${num(m.generation,1)}</td><td>${num(m.selfConsumption??m.self,1)}</td><td>${num(m.import??m.imported,1)}</td><td>${num(m.surplus,1)}</td></tr>`).join('')}</tbody></table></div>`;}
function overview(){const c=selected(),r=state.result;if(!c||!r.choices.length)return notice('Tidak ada kandidat yang memenuhi batas area, anggaran, dan rentang kapasitas. Baseline tetap tersedia. Ubah asumsi untuk mengeksplorasi pilihan lain.','amber');return `${metrics(c)}<div class="result-grid"><section class="panel"><div class="chart-head"><div><h3>Setiap bulan, ceritanya berbeda.</h3><p class="small muted">Produksi surya tahun pertama · kWh</p></div><span class="pill">${r.input.mode==='demo'?'Asumsi awal':'Data manual'}</span></div>${barChart(c.monthly.map(m=>m.generation),months)}<div class="legend"><span><i style="background:#365a45"></i>Produksi AC dalam model</span><span>Surplus belum tentu dapat diekspor.</span></div></section><section class="panel"><h3>Ke mana energinya mengalir?</h3><p>Penggunaan pada jam yang sama, tanpa baterai.</p><div class="flow">${[['Surya dipakai sendiri',c.annualSelfConsumption,c.annualGeneration,'#365a45'],['Potensi surplus surya',c.annualSurplus,c.annualGeneration,'#d9b264'],['Impor dari jaringan',c.annualImport,r.baseline.annualImport,'#b1c39f']].map(([l,v,t,col])=>`<div class="flow-row"><span>${l}</span><strong>${num(v)} kWh</strong></div><div class="track"><span style="width:${Math.min(100,t?Number(v)/Number(t)*100:0)}%;background:${col}"></span></div>`).join('')}</div><div class="flow-foot"><strong>${pct(c.solarFraction)}</strong> kebutuhan listrik dipenuhi surya.<br>Kredit finansial surplus <strong>Rp0</strong>.</div></section></div><div class="result-grid"><section class="panel"><h3>Melihat lebih jauh dari tahun pertama.</h3><p>Arus kas kumulatif tak terdiskonto, setelah investasi, OPEX, dan penggantian.</p>${lineChart([-Number(c.capex),...c.cashflows.map(y=>Number(y.cumulative))],'Arus kas kumulatif setiap tahun')}${c.paybackRecross?notice('Arus kas kumulatif kembali negatif setelah balik modal pertama, akibat biaya berikutnya. Periksa seluruh lintasannya.','amber'):''}<p class="chart-note">Penurunan kurva dapat berasal dari biaya penggantian inverter. Hasil bukan jaminan investasi.</p></section><section class="panel"><h3>Di balik angka ini</h3><ul class="summary-list"><li><span>NPV ${r.input.horizon} tahun</span><strong class="${Number(c.npv)<0?'negative':'positive'}">${rupiah(c.npv)}</strong></li><li><span>Diskonto / degradasi</span><strong>${pct(r.input.discountRate)} / ${pct(r.input.degradation)}</strong></li><li><span>Basis finansial</span><strong>Nominal · komponen energi</strong></li><li><span>Status atap</span><strong>${r.input.roofArea==null?'Belum diperiksa muat atap':'Memenuhi batas luas sederhana'}</strong></li></ul><p class="scope-note" style="margin-top:15px">${Number(c.npv)<0?'NPV negatif pada asumsi ini. Jangan menafsirkan hasil sebagai investasi yang menguntungkan.':'NPV positif hanya pada asumsi model ini, bukan janji keuntungan aktual.'}</p></section></div><details class="panel"><summary style="cursor:pointer;font-size:13px;font-weight:600">Periksa angka energi bulanan</summary><div style="height:18px"></div>${energyTable(c)}</details>`;}
function financeTable(c){return `<div class="table-wrap" role="region" aria-label="Arus kas tahunan" tabindex="0"><table><thead><tr><th>Tahun</th><th>Penghematan</th><th>OPEX</th><th>Penggantian</th><th>Arus kas neto</th><th>Kumulatif</th></tr></thead><tbody><tr><td>0</td><td>Rp0</td><td>Rp0</td><td>Rp0</td><td>${rupiah(-Number(c.capex))}</td><td>${rupiah(-Number(c.capex))}</td></tr>${c.cashflows.map(y=>`<tr><td>${y.year}</td><td>${rupiah(y.savings??y.saving??0)}</td><td>${rupiah(y.opex??0)}</td><td>${rupiah(y.replacement??0)}</td><td>${rupiah(y.cashflow??y.net??y.cf??0)}</td><td class="${Number(y.cumulative)<0?'negative':''}">${rupiah(y.cumulative)}</td></tr>`).join('')}</tbody></table></div>`;}
function finance(){const c=selected();return `<div class="result-grid"><section class="panel"><h3>Biaya yang bisa kamu periksa</h3><p>Tidak ada komponen paket yang ditambahkan dua kali.</p><ul class="summary-list"><li><span>Paket sistem (${num(c.kwp,2)} kWp)</span><strong>${rupiah(c.kwp*state.result.input.capexPerKwp)}</strong></li><li><span>Biaya tetap di luar paket</span><strong>${rupiah(state.result.input.fixedCapex)}</strong></li><li><span>Total CAPEX</span><strong>${rupiah(c.capex)}</strong></li><li><span>OPEX awal per tahun</span><strong>${rupiah(state.result.input.annualOpex)}</strong></li><li><span>Penggantian tahun ${state.result.input.replacementYear}</span><strong>${rupiah(state.result.input.replacementCost)}</strong></li></ul></section><section class="panel"><h3>Nilai uang punya dimensi waktu.</h3>${lineChart([-Number(c.capex),...c.cashflows.map(y=>Number(y.cumulative))],'Grafik arus kas kumulatif')}<p class="chart-note">NPV ${rupiah(c.npv)} pada diskonto ${pct(state.result.input.discountRate)}. Balik modal ${c.payback==null?'belum tercapai dalam horizon':num(c.payback,2)+' tahun'}, berdasarkan perpotongan pertama arus kas kumulatif.</p></section></div><section class="panel"><h3>Seluruh arus kas, tanpa diringkas berlebihan.</h3><p>Produksi terdegradasi dan neraca energi dihitung ulang setiap tahun. Rupiah dibulatkan hanya untuk tampilan.</p>${financeTable(c)}</section>`;}
function sensitivity(){const c=selected();const ss=c.sensitivities||[];const rows=Array.isArray(ss)?ss:Object.entries(ss).map(([key,v])=>({...v,label:v.label||key}));return `<section class="panel"><span class="pill">Satu parameter berubah setiap kali</span><h3 style="margin-top:20px">Bagaimana kalau asumsinya berubah?</h3><p>Produksi dan biaya masing-masing diuji ±15%. Ini rentang eksplorasi, bukan P50, P90, atau probabilitas hasil.</p><div class="table-wrap" role="region" tabindex="0" aria-label="Hasil sensitivitas"><table><thead><tr><th>Skenario</th><th>CAPEX</th><th>Hemat energi / tahun</th><th>Konsumsi sendiri</th><th>NPV</th><th>Balik modal</th></tr></thead><tbody><tr><td>Asumsi dasar</td><td>${rupiah(c.capex)}</td><td>${rupiah(c.annualSavings)}</td><td>${pct(c.selfConsumptionRatio)}</td><td>${rupiah(c.npv)}</td><td>${c.payback==null?'Belum tercapai':num(c.payback,1)+' tahun'}</td></tr>${rows.map(s=>`<tr><td>${esc(s.label||s.name||s.scenario)}</td><td>${rupiah(s.capex)}</td><td>${rupiah(s.annualSavings)}</td><td>${pct(s.selfConsumptionRatio)}</td><td class="${Number(s.npv)<0?'negative':''}">${rupiah(s.npv)}</td><td>${s.payback==null?'Belum tercapai':num(s.payback,1)+' tahun'}</td></tr>`).join('')}</tbody></table></div>${notice('Saat produksi berubah, rasio konsumsi sendiri dihitung ulang terhadap beban tiap jam. Tidak semua tambahan produksi otomatis menjadi tambahan penghematan.')}</section>`;}
function assumptions(){const i=state.result.input;return `<div class="result-grid"><section class="panel"><h3>Jejak asal angka</h3><ul class="summary-list"><li><span>Status sumber</span><strong>${i.mode==='demo'?'Asumsi awal sintetis':i.hourlyData?.productionKwhPerKwp?'AC per jam impor · belum diverifikasi':'Yield manual · belum diverifikasi'}</strong></li><li><span>Lokasi / zona</span><strong>${esc(i.city)} / ${esc(i.timezone)}</strong></li><li><span>Tahun model</span><strong>${i.year} · ${state.result.timeline?.length||state.result.load?.length} interval jam</strong></li><li><span>Sumber yield</span><strong>${esc(i.hourlyData?.productionKwhPerKwp?i.hourlyData.sourceName:i.sourceName||'Asumsi awal sintetis Panelin')}</strong></li><li><span>Periode sumber</span><strong>${esc(i.hourlyData?.productionKwhPerKwp?i.hourlyData.sourcePeriod:i.sourcePeriod||i.year)}</strong></li><li><span>Tarif</span><strong>${rupiah(i.tariff)}/kWh · ${esc(i.tariffGroup||'manual')}</strong></li><li><span>Periode tarif</span><strong>${esc(i.tariffPeriod)}</strong></li><li><span>Data konsumsi</span><strong>${i.hourlyData?.loadKwh?'Seri konsumsi gedung per jam':i.extrapolated?'Satu bulan diekstrapolasi, 11 bulan perkiraan':'12 bulan input pengguna'}</strong></li></ul></section><section class="panel"><h3>Yang dimodelkan, dan batasnya</h3><ul class="summary-list"><li><span>Teknologi</span><strong>On-grid · tanpa baterai</strong></li><li><span>Profil matahari</span><strong>${i.hourlyData?.productionKwhPerKwp?'Data AC per jam impor':i.geo?'Astronomi + transposisi sederhana':'Sintetis pukul 06–18 lokal'}</strong></li>${i.geo?`<li><span>Koordinat / arah depan</span><strong>${num(i.geo.latitude,4)}, ${num(i.geo.longitude,4)} / ${num(i.geo.heading)}°</strong></li><li><span>Bidang 3D / kemiringan</span><strong>${esc(i.geo.roof.type)} / ${esc(i.geo.roof.surface)} / ${num(['flat','l'].includes(i.geo.roof.type)?0:i.geo.roof.pitch)}°</strong></li><li><span>Difus / albedo / rugi tambahan</span><strong>${pct(i.geo.diffuseFraction)} / ${pct(i.geo.albedo)} / ${pct(i.geo.additionalLoss)}</strong></li>`:''}<li><span>Variasi cuaca harian</span><strong>Tidak dimodelkan</strong></li><li><span>Batas inverter / struktur</span><strong>Batas AC per jam / belum diperiksa</strong></li><li><span>Kemiringan / azimut</span><strong>${i.roofTilt==null?'Belum diketahui':num(i.roofTilt)+'°'} / ${i.roofAzimuth==null?'Belum diketahui':num(i.roofAzimuth)+'°'}</strong></li><li><span>Bayangan</span><strong>${i.shading==null?'Belum diketahui':({'0':'Minim bayangan','0.2':'Sebagian terhalang','0.5':'Banyak terhalang'}[String(i.shading)]||pct(i.shading))} · hanya catatan</strong></li><li><span>Energi tertahan batas AC</span><strong>${num(selected()?.annualClippedEnergy??0)} kWh/tahun</strong></li><li><span>Emisi karbon</span><strong>Nonaktif, faktor belum disetujui</strong></li></ul></section></div><section class="panel"><h3>Catatan model yang perlu dibawa bersama hasil</h3><ul class="scope-note">${(state.result.warnings||[]).map(w=>`<li>${esc(typeof w==='string'?w:w.message)}</li>`).join('')}</ul><p class="scope-note">Simulasi ini belum divalidasi dengan dataset pembanding independen atau pilot pengguna. Data biaya, konsumsi, tarif, dan sumber manual tidak diverifikasi otomatis. Periksa kembali ketentuan PLN/ESDM yang berlaku sebelum pemasangan.</p></section>`;}
function results(){if(!state.result)return `<main id="main" class="wrap" tabindex="-1"><div class="section empty-state"><h1 style="font-size:35px">Belum ada hasil simulasi.</h1><p>Mulai dari pemakaian listrikmu atau buka contoh sintetis.</p><a class="btn primary" href="#simulator">Mulai simulasi</a></div></main>`;const r=state.result;return `<main id="main" class="wrap" tabindex="-1"><div class="page-top"><div class="page-meta"><button class="btn ghost back" data-action="edit">${icon('back')} Ubah input simulasi</button><span class="pill">${esc(r.input.city)} · ${r.input.year}</span></div><div class="section-heading" style="margin-bottom:0"><div><div class="eyebrow">Dari angka menjadi pertimbangan</div><h1>Potensinya, kini lebih jelas.</h1></div><div class="result-toolbar"><button class="btn compact" data-action="export">${icon('download')} Simpan JSON</button><button class="btn compact" data-action="print">${icon('print')} Cetak / PDF</button></div></div></div><section class="result-banner"><div><span class="pill dark">${r.input.mode==='demo'?'ESTIMASI · ASUMSI AWAL SINTETIS':'ESTIMASI · DATA MANUAL BELUM DIVERIFIKASI'}</span><h2>${r.input.mode==='demo'?'Lihat kemungkinan, pahami batasnya.':'Bandingkan pilihan dengan asumsi yang terbuka.'}</h2><p>${r.input.mode==='demo'?'Angka surya dan biaya awal adalah contoh sintetis. Pilihan ditampilkan untuk eksplorasi, bukan urutan investasi terbaik.':'Hasil bergantung pada data yang kamu masukkan. Penilaian model bukan verifikasi data atau kelayakan instalasi.'} Penghematan hanya komponen energi, dan surplus bernilai Rp0.</p></div><div class="big-icon">${icon('sun')}</div></section><div data-stale-result ${state.dirty?'':'hidden'}>${notice('Posisi atau atap berubah. Angka di bawah masih hasil sebelumnya. Hitung ulang untuk memperbaruinya.','amber')}<button class="btn compact" data-action="recalculate">Hitung ulang estimasi</button></div>${candidateCards()}<nav class="tabs" aria-label="Bagian hasil">${[['overview','Ringkasan energi'],['roof3d','Atap 3D'],['finance','Biaya & arus kas'],['sensitivity','Uji sensitivitas'],['assumptions','Asumsi & sumber']].map(([v,l])=>`<button data-action="tab" data-value="${v}" class="${state.tab===v?'active':''}" aria-pressed="${state.tab===v}">${l}</button>`).join('')}</nav>${state.tab==='roof3d'?roof3d():r.choices.length?({overview,finance,sensitivity,assumptions}[state.tab])():overview()}<div class="storage-bar"><span>${icon('shield')} Hasil ini milikmu. Penyimpanan di browser bersifat opsional.</span><div class="storage-actions"><button class="link-button" data-action="save">Simpan di browser</button><button class="link-button" data-action="import">Buka JSON</button><button class="link-button" data-action="clear">Hapus data lokal</button></div></div><div class="print-section"><h2>Asumsi, sumber, dan batas hasil</h2>${assumptions()}${r.choices.length?`<h3 style="margin-top:30px">Arus kas tahunan</h3>${financeTable(selected())}`:''}</div><p class="print-only small">Panelin · Dicetak ${new Date().toLocaleString('id-ID')} · Estimasi awal, bukan penawaran, desain teknis, persetujuan pemasangan, atau jaminan penghematan.</p></main>`;}
function methodology(){return `<main id="main" class="wrap" tabindex="-1"><div class="page-top"><div class="eyebrow">Transparan bukan sekadar label</div><h1>Angka yang bisa dijelaskan.</h1><p>Panelin mengikuti prinsip SRS & SDD versi 1.0: satu lokasi, satu meter, on-grid tanpa baterai, dengan sumber dan keterbatasan yang ikut terbawa ke hasil.</p></div><div class="method-grid"><section class="panel">${icon('bolt')}<h3>Energi dihitung per jam.</h3><p>Penghematan bergantung pada pertemuan produksi dan kebutuhan dalam interval yang sama.</p><code>Dipakai sendiri = minimum(produksi, beban)<br>Impor = beban − dipakai sendiri<br>Surplus = produksi − dipakai sendiri</code><p>Surplus siang tidak dapat menutup konsumsi malam. Rasio konsumsi sendiri memakai penyebut produksi; porsi kebutuhan yang dipenuhi surya memakai penyebut beban.</p></section><section class="panel">${icon('chart')}<h3>Keuangan dihitung sepanjang waktu.</h3><p>Arus kas memperhitungkan degradasi produksi, biaya pemeliharaan, dan penggantian inverter yang kamu nyatakan.</p><code>Arus kas awal = −CAPEX<br>Arus kas tahunan = hemat energi − OPEX − penggantian<br>NPV = jumlah arus kas yang didiskontokan</code><p>Balik modal dihitung dari perpotongan pertama arus kas kumulatif tak terdiskonto. Tidak tercapai berarti tidak tercapai, bukan angka tak hingga.</p></section><section class="panel">${icon('layers')}<h3>Asal data selalu dibedakan.</h3><ul><li><strong>Asumsi awal:</strong> contoh sintetis untuk eksplorasi. Bukan data radiasi lokasi dan tanpa ranking personal.</li><li><strong>Tingkat B manual:</strong> yield AC bulanan yang kamu masukkan, dibagi ke profil jam sintetis.</li><li><strong>Tingkat A:</strong> produksi per jam dari sumber valid. Impor CSV lokal tersedia untuk seri energi AC satu tahun yang memenuhi format. Sumber belum diverifikasi otomatis.</li></ul><p>Tingkat data menjelaskan resolusi, bukan jaminan akurasi. Tanpa data geografis, profil bulanan memakai pukul 06–18. Jalur geografis memakai posisi matahari sepanjang tahun dan orientasi bidang 3D, dengan asumsi cahaya difus/pantulan. Keluaran dibatasi rating AC per jam; cuaca harian dan clipping subjam tidak dimodelkan.</p></section><section class="panel">${icon('shield')}<h3>Privasi sejak rancangan.</h3><ul><li>Kalkulasi di browser melalui Web Worker.</li><li>Tidak mengirim konsumsi ke server atau vendor.</li><li>Peta online hanya aktif setelah dipilih. OpenStreetMap menerima IP, asal situs, dan area tampilan peta; tanpa GPS otomatis.</li><li>Penyimpanan lokal hanya setelah pilihan eksplisit.</li><li>JSON membawa input, data terpakai, versi, hasil, dan hash integritas.</li><li>Hash mendeteksi perubahan, bukan tanda tangan atau bukti data benar.</li></ul><button class="btn compact" data-action="import">${icon('upload')} Buka snapshot JSON</button></section><section class="panel">${icon('sun')}<h3>Pilihan tidak selalu lebih besar.</h3><p>Untuk data manual yang memenuhi input, pilihan memakai CAPEX terendah, NPV tertinggi, dan CAPEX terkecil dengan NPV positif ≥90% maksimum. Duplikat dihapus.</p><p>Jika semua NPV negatif, opsi tengah hanya menjadi eksplorasi. Baseline tanpa PLTS selalu hadir. Area dan anggaran membatasi kandidat, bukan membuktikan kelayakan atap.</p></section><section class="panel">${icon('info')}<h3>Jujur tentang yang belum ada.</h3><p>Belum ada sumber surya live, tarif PLN terverifikasi, vendor terkurasi, autentikasi admin, database audit, monitoring inverter, atau estimasi emisi. Biaya dan yield awal bukan angka pasar.</p><p>Benchmark, pembanding hasil produksi independen, uji perangkat nyata, dan audit aksesibilitas masih diperlukan.</p><p>Kredit surplus Rp0 mengikuti asumsi instalasi baru pada <a href="https://esdm.go.id/id/media-center/arsip-berita/aturan-terbaru-plts-atap-terbit-kini-kapasitas-pemasangan-tidak-dibatasi" target="_blank" rel="noopener noreferrer">penjelasan ESDM tentang Permen 2/2024</a>. Pelanggan lama, ketentuan transisi, dan kuota/persetujuan perlu dikonfirmasi langsung.</p><a href="#simulator" class="btn primary compact">Coba simulasinya ${icon('arrow')}</a></section></div>${state.archive?archiveView():''}</main>`;}
function directory(){return `<main id="main" class="wrap" tabindex="-1"><div class="page-top"><div class="eyebrow">Langkah berikutnya, dengan lebih hati-hati</div><h1>Temukan penyedia.<br>Periksa buktinya.</h1><p>Direktori hanya akan menampilkan penyedia nyata setelah proses kurasi. Pemeriksaan dokumen bukan jaminan kualitas instalasi atau dukungan komersial.</p></div><div class="directory-filters"><div class="field"><label for="region-filter">Wilayah layanan</label><select id="region-filter"><option>Semua wilayah</option><option>Jawa Barat</option><option>DKI Jakarta</option><option>Jawa Tengah</option><option>Jawa Timur</option><option>Bali</option><option>Wilayah lainnya</option></select></div><div class="field"><label for="service-filter">Jenis layanan</label><select id="service-filter"><option>Semua layanan</option><option>Survei & perencanaan</option><option>Instalasi PLTS</option><option>Operasi & pemeliharaan</option></select></div></div><div class="empty-state">${icon('shield')}<h2>Belum ada penyedia terkurasi.</h2><p>Direktori masih kosong. Kami tidak mengisi ruang ini dengan vendor fiktif atau badge verifikasi tanpa bukti.</p><span class="pill">0 penyedia · belum ada data terbit</span></div><div class="method-grid"><section class="panel"><h3>Bawa pertanyaan yang tepat.</h3><ul><li>Minta survei struktur, bayangan, dan proteksi kelistrikan.</li><li>Minta rincian harga, komponen paket, garansi, dan pemeliharaan.</li><li>Periksa bukti kompetensi serta tanggal dan lingkup dokumen.</li><li>Konfirmasi izin dan aturan PLN/ESDM yang berlaku.</li></ul></section><section class="panel"><h3>Datamu tidak jadi prospek otomatis.</h3><p>Tidak ada informasi konsumsi atau kontak yang dikirim ke penyedia instalasi dari simulasi ini. Kamu memegang kendali untuk membagikan snapshot atau hasil PDF secara mandiri.</p><a class="btn compact" href="#simulator">Siapkan hasil untuk diskusi ${icon('arrow')}</a></section></div></main>`;}
function archiveView(){return `<div class="panel archive"><span class="pill amber">Arsip · belum diverifikasi replay</span><h3 style="margin-top:20px">Snapshot dengan versi lain</h3><p>Versi ini belum dapat dihitung ulang oleh mesin lokal. Berkas tidak diubah, tidak membuka URL, dan tidak menjalankan kode apa pun.</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${esc(JSON.stringify(state.archive,null,2).slice(0,14000))}</pre></div>`;}
function render(){disposeHelper();disposeRoof();const content={home,simulator:wizard,hasil:results,metodologi:methodology,penyedia:directory}[state.route]||home;$('#app').innerHTML=header()+content()+footer()+`<input type="file" id="import-file" class="hidden" accept="application/json,.json">`+(state.busy?`<div class="busy" role="dialog" aria-modal="true" aria-labelledby="busy-title"><div class="busy-card"><div class="spinner"></div><h2 id="busy-title">Menyusun cerita energimu.</h2><p>Menghitung neraca per jam, opsi kapasitas, arus kas, dan sensitivitas secara lokal.</p><button class="btn compact" data-action="cancel">Batalkan</button></div></div>`:'');bind();disposeHelper=mountFormHelper(state.busy?null:$('.wizard'),{step:state.step,inputMode:state.inputMode,monthlyMode:state.monthlyMode,mode:state.input.mode,geo:!!state.input.geo,hourlyData:state.input.hourlyData,errors:state.errors},walkthroughSession);}
function collect(){const form=$('#simulation-form');if(!form)return;const fd=new FormData(form),priorTimezone=state.input.timezone;const numeric=['year','tariff','roofArea','budget','roofTilt','roofAzimuth','maxKwp','startHour','endHour','baseLoad','capexPerKwp','fixedCapex','annualOpex','horizon','replacementYear','replacementCost','panelWp','panelArea','installationFactor','inverterKw','degradation','discountRate','tariffEscalation','opexEscalation'];for(const [k,v]of fd){if(k in state.input){if(numeric.includes(k))state.input[k]=String(v).trim()===''?null:Number(v);else if(k==='holidays')state.input[k]=String(v).split(',').map(x=>x.trim()).filter(Boolean);else state.input[k]=v;if(k==='timezone'&&state.input.geo&&v!==priorTimezone){state.visualSun={...state.visualSun,timezone:v};if(state.sunDraft){state.sunDraft.values.timezone=v;state.sunDraft.invalidFields=state.sunDraft.invalidFields.filter(k=>k!=='timezone');}}}}
if(state.step===0){state.periodMonth=Number(fd.get('periodMonth'));state.monthlyValue=fd.get('monthlyValue')==null?state.monthlyValue:fd.get('monthlyValue')===''?null:Number(fd.get('monthlyValue'));state.energyCharge=fd.get('energyCharge')==null?state.energyCharge:fd.get('energyCharge')===''?null:Number(fd.get('energyCharge'));state.consent=fd.has('consent');if(state.input.hourlyData?.loadKwh){state.monthlyMode='full';state.input.extrapolated=false;}else if(state.monthlyMode==='average'){const v=state.inputMode==='charge'?(state.input.tariff>0&&state.energyCharge!=null?state.energyCharge/state.input.tariff:null):state.monthlyValue;state.input.monthlyKwh=Array(12).fill(v);state.input.extrapolated=true;}else{state.input.monthlyKwh=months.map((_,i)=>fd.get('month-'+i)===''?null:Number(fd.get('month-'+i)));state.input.extrapolated=false;}}
if(state.step===1){if(!state.input.hourlyData?.productionKwhPerKwp)state.input.monthlyYield=months.map((_,i)=>fd.get('yield-'+i)===''?null:Number(fd.get('yield-'+i)));state.input.shading=fd.get('shading')===''?null:Number(fd.get('shading'));if(state.input.geo){for(const key of ['diffuseFraction','albedo','additionalLoss']){const value=fd.get('geo-'+key);if(value!==null)state.input.geo[key]=value===''?null:Number(value);}syncGeographicInput();}}
if(state.step===2)state.input.activeDays=days.map((_,i)=>i).filter(i=>fd.has('day-'+i));if(state.step===3)state.saveEnabled=fd.has('saveEnabled');state.input.consumptionSourceMonth=state.periodMonth+1;}
function validateStep(){const errors=state.step>=1?[...geographicDraftErrors()]:[];if(state.step===0){if(state.monthlyMode==='average'&&!state.consent)errors.push({message:'Pilih persetujuan ekstrapolasi atau isi konsumsi 12 bulan.'});if(state.inputMode==='charge'&&(state.input.tariff<=0||state.energyCharge==null))errors.push({message:'Konversi biaya memerlukan tarif positif dan komponen energi yang diketahui.'});}
const fieldsByStep=[['year','tariff','monthlyKwh','tariffGroup','tariffPeriod'],['city','timezone','roofArea','budget','roofTilt','roofAzimuth','monthlyYield','maxKwp','sourceName','sourcePeriod','geo','hourlyData'],['activeDays','startHour','endHour','baseLoad','holidays'],['capexPerKwp','fixedCapex','annualOpex','horizon','replacementYear','replacementCost','panelWp','panelArea','installationFactor','inverterKw','degradation','discountRate','tariffEscalation','opexEscalation']];const check=validateInput(state.input);for(const e of check.errors||[]){const path=typeof e==='string'?e:e.field||e.path||'';const alias={2:['Hari aktif','Tanggal libur','Jam selesai'],1:['Zona waktu','Rentang kapasitas'],0:['Status ekstrapolasi']};if(fieldsByStep[state.step].some(f=>path.startsWith(f))||(alias[state.step]||[]).some(f=>path.startsWith(f)))errors.push(typeof e==='string'?{message:e}:e);}state.errors=errors;return errors.length===0;}
async function calculate(){collect();const geoErrors=geographicDraftErrors();if(geoErrors.length){state.errors=geoErrors;state.step=1;if(state.route!=='simulator')navigate('simulator');else render();return;}if(!validateStep()){render();$('.notice.error')?.scrollIntoView({block:'center'});return;}const check=validateInput(state.input);if(!check.valid){state.errors=check.errors.map(e=>typeof e==='string'?{message:e}:e);render();return;}state.busy=true;state.result=null;state.archive=null;render();const current=state.job+1;try{const result=await runWorker('simulate',structuredClone(state.input));if(current!==state.job)return;state.result=result;state.selected=Math.min(1,Math.max(0,result.choices.length-1));state.tab='overview';state.busy=false;state.dirty=false;if(state.saveEnabled)saveLocal(false);navigate('hasil');}catch(err){state.busy=false;state.errors=err.errors?.length?err.errors:[{message:err.message||'Perhitungan gagal. Periksa input.'}];render();}}
// Retain the original storage keys so the Panelin rename preserves saved inputs.
function saveLocal(feedback=true){if(geographicDraftErrors().length){notify('Perbaiki input lokasi/zona/arah sebelum menyimpan, atau nonaktifkan hubungan geografis.');return;}try{localStorage.setItem('suryajelas:input:v1',JSON.stringify(state.input));localStorage.setItem('suryajelas:visual:v1',JSON.stringify(state.visualRoof));localStorage.setItem('suryajelas:sun:v1',JSON.stringify(state.visualSun));if(feedback)notify('Input tersimpan hanya di browser ini. Kamu dapat menghapusnya kapan saja.');}catch{notify('Penyimpanan browser tidak tersedia atau penuh. Gunakan Simpan JSON.');}}
async function exportJSON(){if(!state.result||state.dirty||geographicDraftErrors().length){notify('Perbaiki input dan hitung ulang terlebih dahulu sebelum ekspor.');return;}state.busy=true;render();try{const snapshot=await runWorker('snapshot',state.result.input);const blob=new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`Panelin-${state.result.input.year}-${state.result.input.mode}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Snapshot JSON disiapkan untuk diunduh, lengkap dengan sumber dan asumsi.');}catch(e){notify('Ekspor gagal: '+e.message);}finally{state.busy=false;render();}}
async function importJSON(file){if(!file)return;if(file.size>10*1024*1024){notify('Berkas melebihi batas 10 MiB.');return;}state.busy=true;render();try{const text=await file.text();const parsed=JSON.parse(text);const result=await runWorker('replay',text);if(result.status==='archive'||result.replayed===false){state.archive=result;state.busy=false;navigate('metodologi');return;}state.result=result;state.input=structuredClone(result.input);state.sunDraft=null;state.periodMonth=state.input.consumptionSourceMonth-1;state.selected=0;state.tab='overview';state.visualRoof=result.input.geo?normalizeRoof(result.input.geo.roof):{...DEFAULT_ROOF};state.visualSun=result.input.geo?normalizeSun({...DEFAULT_SUN,...result.input.geo,timezone:result.input.timezone}):{...DEFAULT_SUN};state.dirty=false;state.busy=false;navigate('hasil');notify('Snapshot berhasil diverifikasi dan dihitung ulang tanpa jaringan.');}catch(e){if(e.code==='UNSUPPORTED_ENGINE'||e.code==='UNSUPPORTED_MODEL_VERSION'||/versi.*(tidak|belum)|unsupported.*version/i.test(e.message)){try{const archived=JSON.parse(await file.text());state.archive={...inspectSnapshot(archived),input:archived.input,results:archived.results};state.busy=false;navigate('metodologi');notify('Snapshot dibuka sebagai arsip. Versi mesin tidak tersedia.');return;}catch{}}notify('Snapshot tidak dapat dibuka: '+(e.message||'format tidak valid'));state.busy=false;render();}}
function bind(){disposeRoof=mountRoofView($('.roof-lab'),state.visualRoof,{sun:state.visualSun,sunDraft:state.sunDraft,onSunDraftChange:acceptSunDraft,onSunChange:value=>{state.visualSun=value;syncGeographicInput();},panelCount:state.route==='hasil'?(selected()?.panelCount??0):undefined,panelArea:state.input.panelArea,onChange:value=>{state.visualRoof=value;syncGeographicInput();}});$$('[data-action]').forEach(el=>el.addEventListener('click',async()=>{const a=el.dataset.action,v=el.dataset.value;if(a==='demo'){state.input=initialInput();state.sunDraft=null;state.input.mode='demo';state.input.extrapolated=true;state.input.monthlyKwh=Array(12).fill(600);state.step=3;state.consent=true;state.errors=[];state.inputMode='kwh';state.monthlyMode='average';await calculate();}else if(a==='hourly-template'){collect();downloadHourlyTemplate();}else if(a==='remove-hourly'){state.input.hourlyData=null;state.result=null;state.dirty=true;render();notify('Seri per jam dilepas. Total bulanan tetap ada sebagai input manual.');}else if(a==='recalculate'){state.step=3;await calculate();}else if(a==='segment'){collect();state.dirty=true;state.result=null;state.input.segment=v;const map={household:[17,23,[0,1,2,3,4,5,6],.45],school:[7,15,[1,2,3,4,5],.12],business:[8,18,[1,2,3,4,5,6],.25]};[state.input.startHour,state.input.endHour,state.input.activeDays,state.input.baseLoad]=map[v];state.errors=[];render();}else if(a==='step'||a==='prev'){collect();const to=a==='prev'?state.step-1:Number(v);if(to>state.step&&!validateStep()){render();return;}state.step=to;state.errors=[];render();$('#main').scrollIntoView();}else if(['input-mode','monthly-mode','data-mode'].includes(a)){collect();state.dirty=true;state.result=null;if(a==='input-mode')state.inputMode=v;else if(a==='monthly-mode')state.monthlyMode=v;else{state.input.mode=v;if(v==='manual'){state.input.sourceName='';state.input.sourcePeriod='';}else{state.input.hourlyData=null;state.input.monthlyYield=[...DEFAULT_INPUT.monthlyYield];state.input.sourceName='Asumsi awal sintetis Panelin';state.input.sourcePeriod=String(state.input.year);}}state.errors=[];render();}else if(a==='tab'){state.tab=v;render();}else if(a==='candidate'){state.selected=Number(v);render();}else if(a==='edit'){state.step=0;state.dirty=true;state.result=null;state.periodMonth=state.input.consumptionSourceMonth-1;state.monthlyValue=state.input.monthlyKwh[0];state.monthlyMode=state.input.extrapolated?'average':'full';navigate('simulator');}else if(a==='cancel'){worker?.terminate();worker=null;for(const p of pending.values())p.reject({message:'Perhitungan dibatalkan.'});pending.clear();state.job++;state.busy=false;render();notify('Perhitungan dibatalkan. Tidak ada hasil baru.');}else if(a==='save')saveLocal();else if(a==='clear'){try{localStorage.removeItem('suryajelas:input:v1');localStorage.removeItem('suryajelas:visual:v1');localStorage.removeItem('suryajelas:sun:v1');notify('Data Panelin yang tersimpan di browser telah dihapus. Hasil di layar tetap ada sampai halaman ditutup.');}catch{notify('Penyimpanan browser tidak dapat diakses.');}}else if(a==='export')await exportJSON();else if(a==='import')$('#import-file').click();else if(a==='print'){if(state.dirty||geographicDraftErrors().length)notify('Perbaiki input dan hitung ulang sebelum mencetak.');else window.print();}else if(a==='privacy'){notify('Kalkulasi lokal. Input disimpan hanya jika kamu memilih. Peta opsional mengirim IP, asal situs, dan area tampilan ke OpenStreetMap setelah diaktifkan; tanpa GPS otomatis.');}}));if(state.busy){$('.header')?.setAttribute('inert','');$('#main')?.setAttribute('inert','');$('.footer')?.setAttribute('inert','');$('.busy button')?.focus();$('.busy')?.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();$('.busy button')?.focus();}});}$('#simulation-form')?.addEventListener('submit',e=>{e.preventDefault();collect();if(!validateStep()){render();$('.notice.error')?.scrollIntoView({block:'center'});return;}if(state.step<3){state.step++;state.errors=[];render();$('.wizard').scrollIntoView({block:'start'});}else calculate();});$('#simulation-form')?.addEventListener('change',e=>{state.dirty=true;state.result=null;collect();if(state.step===2&&['startHour','endHour','baseLoad'].includes(e.target.name)||state.input.geo&&e.target.name==='timezone')render();});$('#import-file')?.addEventListener('change',e=>importJSON(e.target.files[0]));$('#hourly-file')?.addEventListener('change',e=>importHourlyFile(e.target.files[0]));$('#geo-enabled')?.addEventListener('change',e=>{collect();if(e.target.checked){state.input.geo={latitude:state.visualSun.latitude,longitude:state.visualSun.longitude,heading:state.visualSun.heading,roof:{},diffuseFraction:.5,albedo:.2,additionalLoss:0};state.input.timezone=state.visualSun.timezone;syncGeographicInput();}else state.input.geo=null;state.dirty=true;state.result=null;render();});}
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main')?.focus();return;}state.route=location.hash.slice(1)||'home';if(!['home','simulator','hasil','metodologi','penyedia'].includes(state.route))state.route='home';render();window.scrollTo(0,0);});
try{const saved=localStorage.getItem('suryajelas:input:v1');if(saved){const input=JSON.parse(saved);if(validateInput(input).valid){state.input=input;state.periodMonth=input.consumptionSourceMonth-1;state.monthlyValue=input.monthlyKwh[0];state.monthlyMode=input.extrapolated?'average':'full';state.saveEnabled=true;}}}catch{}
try{const visual=localStorage.getItem('suryajelas:visual:v1');if(visual)state.visualRoof=normalizeRoof(JSON.parse(visual));}catch{}
try{const sun=localStorage.getItem('suryajelas:sun:v1');if(sun)state.visualSun=normalizeSun(JSON.parse(sun));}catch{}
if(state.input.geo){state.visualRoof=normalizeRoof(state.input.geo.roof);state.visualSun=normalizeSun({...state.visualSun,...state.input.geo,timezone:state.input.timezone});}
state.route=location.hash.slice(1)||'home';render();
